// Semafor cu automat finit Moore și mod automat/manual
enum State {GREEN, YELLOW, RED};
State st = GREEN; bool manualMode=false; unsigned long tState=0;
const uint16_t delayMs[3] = {5000, 1000, 5000};                 // durate stări
