  digitalWrite(LED_G, s==GREEN); digitalWrite(LED_Y, s==YELLOW); digitalWrite(LED_R, s==RED);
}
State nextAuto(State s){ return s==GREEN ? YELLOW : (s==YELLOW ? RED : GREEN); } // tranziții ciclice
void setup(){ pinMode(BTN,INPUT_PULLUP); Serial.begin(9600); }
void loop(){
  static bool oldBtn=1; bool btn=digitalRead(BTN);              // citire buton mod/tranziție
  if(oldBtn==1 && btn==0) manualMode = !manualMode;             // front descendent: schimbă modul
  oldBtn=btn;
  unsigned long now=millis();
  setLights(st);                                                // acțiune Moore
  if(!manualMode && now-tState>=delayMs[st]){ st=nextAuto(st); tState=now; } // mod automat cu timer
  if(manualMode && oldBtn==0){ st=nextAuto(st); tState=now; }   // mod manual: un pas la buton
  Serial.print(manualMode?"MAN ":"AUTO "); Serial.println(st); // raportare STDIO/serial
}

