// Motor DC controlat On/Off cu histerezis; pragurile vin prin interfața serială
#define MOTOR_EN 9
int thOn=40, thOff=60; bool motorOn=false;
void readThresholds(){
  if(Serial.available()){                                      // format: 40 60\n
    int a=Serial.parseInt(); int b=Serial.parseInt();           // citire TH_ON și TH_OFF
    if(a<b){ thOn=a; thOff=b; }                                 // condiție obligatorie pentru histerezis
  }
}
void setup(){ Serial.begin(9600); lcd.begin(16,2); pinMode(MOTOR_EN,OUTPUT); }
void loop(){
  readThresholds();                                             // configurare de la utilizator
  int x = map(analogRead(A0),0,1023,0,100);                     // feedback proces: viteză/temperatură
  if(!motorOn && x < thOn)  motorOn=true;                       // prag inferior: pornire
  if( motorOn && x > thOff) motorOn=false;                      // prag superior: oprire
  digitalWrite(MOTOR_EN, motorOn);                              // comandă driver motor
  lcd.setCursor(0,0); lcd.print("x="); lcd.print(x);           // raportare valoare
  lcd.setCursor(0,1); lcd.print(motorOn?"MOTOR ON ":"MOTOR OFF"); // raportare stare
  delay(50);                                                    // perioadă control
}

// FSM pentru sistem de securitate ușă: STANDBY, DOOR_CLOSED, DOOR_OPEN
enum DoorState {STANDBY, DOOR_CLOSED, DOOR_OPEN};
DoorState st=STANDBY;
void setup(){ pinMode(BTN,INPUT_PULLUP); Serial.begin(9600); }
void loop(){
  static bool oldBtn=1; bool btn=digitalRead(BTN);              // buton/contact ușă
  bool event = (oldBtn==1 && btn==0); oldBtn=btn;               // detecție front pentru comutare
  switch(st){
    case STANDBY:     if(event) st=DOOR_CLOSED; break;          // activare sistem
    case DOOR_CLOSED: if(event) st=DOOR_OPEN;   break;          // ușa s-a deschis
    case DOOR_OPEN:   if(event) st=DOOR_CLOSED; break;          // ușa s-a închis
  }
  if(st==STANDBY) Serial.println("STANDBY");                   // ieșire textuală pe serial
  if(st==DOOR_CLOSED) Serial.println("USA INCHISA");
  if(st==DOOR_OPEN) Serial.println("USA DESCHISA");
  delay(100);                                                   // debounce simplu + recurență
}

// Protecție motor DC: oprire la depășirea temperaturii critice
#define MOTOR_EN 9
uint8_t faultCnt=0; bool motorAllowed=true;
void setup(){ Serial.begin(9600); pinMode(MOTOR_EN,OUTPUT); }
void loop(){
  int temp = map(analogRead(A0),0,1023,0,150);                  // temperatură motor [°C]
  int critical = map(analogRead(A1),0,1023,40,120);             // prag critic din potențiometru
  bool symptom = (temp > critical);                             // simptom threshold over-temperature
  if(symptom && faultCnt<10) faultCnt++;                        // calificare prin counter
  if(!symptom && faultCnt>0) faultCnt--;                        // descalificare lentă
  if(faultCnt>=5) motorAllowed=false;                           // diagnostic calificat -> protecție
  if(!symptom && temp < critical-5) motorAllowed=true;           // reset cu histerezis
  digitalWrite(MOTOR_EN, motorAllowed);                         // oprire motor la fault
  Serial.print("T="); Serial.print(temp); Serial.print(" TH="); Serial.print(critical);
  Serial.println(motorAllowed ? " MOTOR_OK" : " MOTOR_OFF_FAULT"); // raportare stare
  delay(100);
}

