// MCU1: senzor vibrații, mediere ponderată, transmitere serială
#define CMD_VIB 0x31
float filt=0.0f; const float alpha=0.20f;
uint8_t crc8(uint8_t *b,uint8_t n){ uint8_t c=0; for(uint8_t i=0;i<n;i++) c^=b[i]; return c; }
int16_t filterVibration(){
  int raw = analogRead(A0);                                     // achiziție vibrație
  raw = constrain(raw, 0, 1023);                                // saturare software
  filt = alpha*raw + (1.0f-alpha)*filt;                         // filtru mediere ponderată
  return (int16_t)filt;                                         // valoare filtrată pentru protocol
}
void sendVib(int16_t v){
  uint8_t p[4]={CMD_VIB,2,highByte(v),lowByte(v)};              // CMD+LEN+DATA
  Serial.write(STX); Serial.write(p,4); Serial.write(crc8(p,4)); Serial.write(ETX); // cadru complet
}
void loop(){ sendVib(filterVibration()); delay(20); }           // recurență 20 ms

