bool receiveRGB(uint8_t *r,uint8_t *g,uint8_t *b){
  uint8_t p[6];                                                // CMD LEN R G B CRC
  if(!readFrame(p,6)) return false;                            // parser STX/ETX comun
  if(p[0]!=CMD_RGB || p[1]!=3) return false;                    // validare comandă/lungime
  if(crc8(p,5)!=p[5]) return false;                             // verificare CRC
  *r=p[2]; *g=p[3]; *b=p[4]; return true;                       // valori PWM 0..255
}
