  if(receiveRGB(&r,&g,&b)){                                    // aplicare numai la pachet valid
    analogWrite(PIN_R,r); analogWrite(PIN_G,g); analogWrite(PIN_B,b); // duty-cycle RGB
    Serial.println("ACK RGB");                                  // raportare stare
  } else {
    Serial.println("WAIT/ERR");                                 // diagnoză comunicare
  }
}

