// FreeRTOS: 3 taskuri - achiziție senzor, afișare LCD, raportare serială
QueueHandle_t qSensor;                                         // comunicare sigură între taskuri
typedef struct { int value; bool valid; } SensorMsg;
void TaskSensor(void *p){
  SensorMsg m;
  for(;;){
    int raw=analogRead(A0);                                    // achiziție periodică
    m.value=map(raw,0,1023,0,100);                              // conversie în unități aplicație
    m.valid=true;                                               // aici se poate adăuga diagnoză
    xQueueOverwrite(qSensor,&m);                                // trimite ultima valoare
    vTaskDelay(pdMS_TO_TICKS(50));                              // recurență 50 ms
  }
}
void TaskLCD(void *p){
  SensorMsg m;
  for(;;){
    if(xQueueReceive(qSensor,&m,pdMS_TO_TICKS(100))){           // primește valoarea senzorului
      lcd.setCursor(0,0); lcd.print("S="); lcd.print(m.value); // afișare LCD
    }
  }
}
void TaskSerial(void *p){
  SensorMsg m;
  for(;;){
    if(xQueuePeek(qSensor,&m,0)){                               // citește fără a consuma mesajul
      Serial.print("STATE OK, S="); Serial.println(m.value);    // raportare serială
    }
    vTaskDelay(pdMS_TO_TICKS(500));                             // raportare mai rară
  }
}
void setup(){ Serial.begin(9600); lcd.begin(16,2); qSensor=xQueueCreate(1,sizeof(SensorMsg)); xTaskCreate(TaskSensor,"sns",128,NULL,2,NULL); xTaskCreate(TaskLCD,"lcd",128,NULL,1,NULL); xTaskCreate(TaskSerial,"ser",128,NULL,1,NULL); vTaskStartScheduler(); }
