// MCU2: parser + manager simplu de erori
uint8_t errCnt=0;
void processFrame(uint8_t *p){
  bool ok = (p[0]==CMD_DATA && p[1]==1 && crc8(p,3)==p[3]);      // validare comandă/lungime/CRC
  if(ok){
    errCnt=0;                                                   // eroarea dispare la cadru valid
    lcd.setCursor(0,0); lcd.print("RX OK DATA="); lcd.print(p[2]);
  } else {
    if(errCnt<10) errCnt++;                                     // calificare diagnostic prin counter
    lcd.setCursor(0,0); lcd.print("CRC ERROR     ");
  }
  if(errCnt>=3){ lcd.setCursor(0,1); lcd.print("COM FAULT"); }  // diagnostic calificat
}
void loop(){
  uint8_t p[4];
  if(readFrame(p,4)) processFrame(p);                           // readFrame verifică STX/ETX și timeout
}

// Control PID pentru viteză motor DC cu encoder și PWM
float Kp=1.0f, Ki=0.1f, Kd=0.01f, setpoint=100.0f;
float integ=0.0f, prevErr=0.0f; unsigned long lastMs=0;
void readPIDParams(){
  if(Serial.available()){                                      // format: Kp Ki Kd SP\n
    Kp=Serial.parseFloat(); Ki=Serial.parseFloat(); Kd=Serial.parseFloat(); setpoint=Serial.parseFloat(); // configurare
  }
}
void controlTask(){
  unsigned long now=millis(); float dt=(now-lastMs)/1000.0f; if(dt<=0) return; lastMs=now; // perioadă discretă
  float speed = readEncoderRpm();                               // feedback encoder
  float err = setpoint - speed;                                 // eroare de control
  integ += err*dt; integ = constrain(integ,-500,500);            // integrală cu anti-windup
  float deriv = (err-prevErr)/dt; prevErr=err;                   // derivata erorii
  float u = Kp*err + Ki*integ + Kd*deriv;                        // lege PID discretă
  int duty = constrain((int)u,0,255);                            // saturare la domeniul PWM
  analogWrite(MOTOR_PWM,duty);                                  // comandă driver motor
  lcd.setCursor(0,0); lcd.print("RPM="); lcd.print(speed);      // raportare LCD
  lcd.setCursor(0,1); lcd.print("PWM="); lcd.print(duty);
}
void loop(){ readPIDParams(); controlTask(); delay(10); }        // recurență control aprox. 10 ms
